export function getReportTypeLabel(code) {
  switch (code) {
    case 'W41P': return 'Pre Delivery';
    case 'W41N': return 'Delivery';
    case 'W411': return '1st Service';
    case 'W412': return '2nd Service';
    case 'W413': return '3rd Service';
    case 'W30': return 'Storage';
    case 'W51D': return 'Condition';
    case 'W41X':
    default:
      return 'Add. Service';
  }
}

export function mapReportToEventCode(report) {
  const code = (report.report_type || '').trim().toUpperCase();
  if (['W41P', 'W41N', 'W411', 'W412', 'W413', 'W41X', 'W30', 'W51D', 'W70', 'W70F'].includes(code)) {
    return code;
  }
  const sType = (report.service_type || report.report_type || '').toUpperCase();
  if (sType.includes('PRE-DELIVERY') || sType.includes('PDI')) return 'W41P';
  if (sType.includes('NEW') || sType.includes('DELIVERY')) return 'W41N';
  if (sType.includes('1ST') || sType.includes('250')) return 'W411';
  if (sType.includes('2ND') || sType.includes('500')) return 'W412';
  if (sType.includes('3RD') || sType.includes('1000')) return 'W413';
  if (sType.includes('STORAGE')) return 'W30';
  if (sType.includes('CONDITION')) return 'W51D';
  return 'W41X';
}

function getEarliestDateByCode(observedReports, code) {
  const matching = observedReports
    .filter(([reportCode, date]) => reportCode === code && date && String(date).trim().length > 0)
    .map(([, date]) => String(date).trim())
    .sort();
  return matching[0] || null;
}

export function buildLifecycleRecordFromProps({
  machineNumber,
  model,
  responsibleEngineer = null,
  preDeliveryDate,
  deliveryDate,
  firstServiceDate,
  secondServiceDate,
  thirdServiceDate,
  latestReportDate,
  latestReportCode,
  latestReportType,
  latestSmr,
  addServiceCount,
  observedReports = [],
  machineId = null,
  isLiveEqpc = false,
  syncedAt = null,
}) {
  const currentMonth = getCurrentMonthKey();
  const { strictGaps, nonCreatedReports, monthlyGaps } = analyzeMissingLifecycleMonths({
    observedReports,
    firstServiceDate,
    secondServiceDate,
    thirdServiceDate,
    deliveryDate,
    currentMonth,
  });

  const missingReports = [
    { label: 'Pre Delivery', missing: !preDeliveryDate },
    { label: 'Delivery', missing: !deliveryDate },
    { label: '1st Service', missing: !firstServiceDate },
    { label: '2nd Service', missing: !secondServiceDate },
    { label: '3rd Service', missing: !thirdServiceDate && shouldExpectThirdService(deliveryDate, currentMonth) },
  ].filter((item) => item.missing).map((item) => item.label);

  const hasStrictGap = strictGaps.length > 0;
  const hasNonCreated = nonCreatedReports.length > 0;
  const hasMonthlyGap = hasStrictGap || hasNonCreated;
  const getMilestoneSmr = (code, date) => {
    if (!date) return null;
    const found = observedReports.find(([c, d]) => c === code && d === date);
    return (found && found[2] != null && !isNaN(Number(found[2]))) ? Number(found[2]) : null;
  };

  const preDeliverySmr = getMilestoneSmr('W41P', preDeliveryDate);
  const deliverySmr = getMilestoneSmr('W41N', deliveryDate);
  const firstServiceSmr = getMilestoneSmr('W411', firstServiceDate);
  const secondServiceSmr = getMilestoneSmr('W412', secondServiceDate);
  const thirdServiceSmr = getMilestoneSmr('W413', thirdServiceDate);

  return {
    machineNumber,
    model,
    machineId,
    isLiveEqpc,
    syncedAt,
    responsibleEngineer,
    preDeliveryDate,
    preDeliverySmr,
    deliveryDate,
    deliverySmr,
    firstServiceDate,
    firstServiceSmr,
    secondServiceDate,
    secondServiceSmr,
    thirdServiceDate,
    thirdServiceSmr,
    latestReportDate,
    latestReportCode,
    latestReportType,
    latestSmr,
    addServiceCount,
    observedReports,
    workingStatus: 'not_working',
    strictGaps,
    nonCreatedReports,
    monthlyGaps, // combined for backwards compatibility
    missingReports,
    hasStrictGap,
    hasNonCreated,
    hasMonthlyGap,
    hasLifecycleGap: missingReports.length > 0 || hasStrictGap,
    status: hasStrictGap ? 'Historical Gaps' : (hasNonCreated ? 'Pending Monthly' : 'Lifecycle Current'),
    statusTone: hasStrictGap ? 'warning' : (hasNonCreated ? 'neutral' : 'ready'),
    nextAction: buildStrictNextAction(missingReports, strictGaps, nonCreatedReports),
    milestones: [
      { label: 'Pre Delivery', date: preDeliveryDate, code: 'W41P', smr: preDeliverySmr },
      { label: 'Delivery', date: deliveryDate, code: 'W41N', smr: deliverySmr },
      { label: '1st Service', date: firstServiceDate, code: 'W411', smr: firstServiceSmr },
      { label: '2nd Service', date: secondServiceDate, code: 'W412', smr: secondServiceSmr },
      { label: '3rd Service', date: thirdServiceDate, code: 'W413', smr: thirdServiceSmr },
    ],
    serviceModeLabel: 'Not working',
  };
}

export function buildDynamicLifecycleRecords(generatedReports = [], machinesList = [], liveEqpData = null) {
  const reportsByMachine = new Map();
  for (const r of generatedReports) {
    const mNum = String(r.machine_number || r.machine?.machineNumber || r.machine?.machine_number || '').trim();
    if (!mNum) continue;
    if (!reportsByMachine.has(mNum)) reportsByMachine.set(mNum, []);
    reportsByMachine.get(mNum).push(r);
  }

  const liveMachinesMap = (liveEqpData && typeof liveEqpData === 'object') ? (liveEqpData.machines || liveEqpData) : {};

  const machineNumbers = new Set(BASE_LIFECYCLE_ROWS.map(([num]) => String(num)));
  for (const mNum of reportsByMachine.keys()) {
    machineNumbers.add(mNum);
  }
  for (const m of machinesList) {
    const mNum = String(m.machine_number || m.machineNumber || '').trim();
    if (mNum) machineNumbers.add(mNum);
  }
  for (const mNum of Object.keys(liveMachinesMap)) {
    const trimmed = String(mNum).trim();
    if (trimmed) machineNumbers.add(trimmed);
  }

  const records = [];

  for (const machineNumber of machineNumbers) {
    const baseRow = BASE_LIFECYCLE_ROWS.find(([num]) => String(num) === machineNumber);
    const machineObj = machinesList.find((m) => String(m.machine_number || m.machineNumber) === machineNumber);
    const genReports = reportsByMachine.get(machineNumber) || [];
    const liveMachine = liveMachinesMap[machineNumber];

    const model = liveMachine?.model || (baseRow ? baseRow[1] : (machineObj?.machine_type || machineObj?.machineType || 'HM400'));
    const responsibleEngineer = machineObj?.responsible_engineer || machineObj?.responsibleEngineer || null;
    
    // Prioritize genuine Komatsu Equipment Care live reports over baseline excel rows
    let baseObserved = [];
    if (liveMachine && Array.isArray(liveMachine.reports) && liveMachine.reports.length > 0) {
      baseObserved = liveMachine.reports.map((r) => [r.eventCode, r.date, r.smr, r.eventName]);
    } else if (OBSERVED_REPORTS[machineNumber]) {
      baseObserved = [...OBSERVED_REPORTS[machineNumber]];
    }

    const observedSet = new Set(baseObserved.map(([code, date]) => `${code}_${date}`));

    for (const gr of genReports) {
      const code = mapReportToEventCode(gr);
      const rawDate = gr.service_date || gr.created_at;
      if (!rawDate) continue;
      const date = String(rawDate).slice(0, 10);
      const key = `${code}_${date}`;
      if (!observedSet.has(key)) {
        observedSet.add(key);
        baseObserved.push([code, date, gr.smr ? Number(gr.smr) : null, gr.report_type || gr.service_type || 'Generated Report']);
      }
    }

    // Sort observed reports chronologically descending (latest first)
    baseObserved.sort((a, b) => b[1].localeCompare(a[1]));

    const preDeliveryDate = getEarliestDateByCode(baseObserved, 'W41P') || baseRow?.[2] || null;
    const deliveryDate = getEarliestDateByCode(baseObserved, 'W41N') || baseRow?.[3] || null;
    const firstServiceDate = getEarliestDateByCode(baseObserved, 'W411') || baseRow?.[4] || null;
    const secondServiceDate = getEarliestDateByCode(baseObserved, 'W412') || baseRow?.[5] || null;
    const thirdServiceDate = getEarliestDateByCode(baseObserved, 'W413') || baseRow?.[6] || null;

    let latestReportDate = baseObserved[0] ? baseObserved[0][1] : (baseRow?.[7] || null);
    let latestReportCode = baseObserved[0] ? baseObserved[0][0] : (baseRow?.[8] || 'W41X');
    let latestReportType = baseObserved[0] ? getReportTypeLabel(baseObserved[0][0]) : (baseRow?.[9] || 'Add. Service');
    
    // Extract highest SMR from live reports if available
    let liveMaxSmr = null;
    if (liveMachine && Array.isArray(liveMachine.reports)) {
      for (const r of liveMachine.reports) {
        if (r.smr != null && !isNaN(Number(r.smr))) {
          if (liveMaxSmr == null || Number(r.smr) > liveMaxSmr) {
            liveMaxSmr = Number(r.smr);
          }
        }
      }
    }
    let latestSmr = liveMaxSmr ?? (baseRow?.[10] ?? (machineObj?.last_smr ? Number(machineObj.last_smr) : null));

    for (const gr of genReports) {
      if (gr.smr && Number(gr.smr) > (latestSmr || 0)) {
        latestSmr = Number(gr.smr);
      }
    }

    const addServiceCount = baseObserved.filter(([c]) => ['W41X', 'W30', 'W51D'].includes(c)).length;

    const record = buildLifecycleRecordFromProps({
      machineNumber,
      model,
      machineId: liveMachine?.machineId || null,
      isLiveEqpc: Boolean(liveMachine && liveMachine.reports?.length > 0),
      syncedAt: liveMachine?.syncedAt || liveEqpData?.lastSync || null,
      responsibleEngineer,
      preDeliveryDate,
      deliveryDate,
      firstServiceDate,
      secondServiceDate,
      thirdServiceDate,
      latestReportDate,
      latestReportCode,
      latestReportType,
      latestSmr,
      addServiceCount,
      observedReports: baseObserved,
    });

    records.push(record);
  }

  return records;
}

export const EQP_LIFECYCLE_RECORDS = BASE_LIFECYCLE_ROWS.map(([
  machineNumber,
  model,
  preDeliveryDate,
  deliveryDate,
  firstServiceDate,
  secondServiceDate,
  thirdServiceDate,
  latestReportDate,
  latestReportCode,
  latestReportType,
  latestSmr,
  addServiceCount,
]) =>
  buildLifecycleRecordFromProps({
    machineNumber,
    model,
    preDeliveryDate,
    deliveryDate,
    firstServiceDate,
    secondServiceDate,
    thirdServiceDate,
    latestReportDate,
    latestReportCode,
    latestReportType,
    latestSmr,
    addServiceCount,
    observedReports: OBSERVED_REPORTS[machineNumber] || [],
  })
);

export function getPrecedingReport(observedReports = [], targetMonth) {
  const chronological = [...observedReports]
    .filter(([, date]) => date && toMonthKey(date) < targetMonth)
    .sort((a, b) => b[1].localeCompare(a[1]));

  if (chronological.length > 0) {
    const [code, date, smr, name] = chronological[0];
    return { code, date, smr: smr != null && !isNaN(Number(smr)) ? Number(smr) : null, name };
  }
  return null;
}

export function analyzeMissingLifecycleMonths({
  observedReports = [],
  firstServiceDate,
  secondServiceDate,
  thirdServiceDate,
  deliveryDate,
  currentMonth = getCurrentMonthKey(),
}) {
  const observedMonthsSet = new Set(
    observedReports.map(([, date]) => (date ? toMonthKey(date) : null)).filter(Boolean)
  );

  let latestObservedMonth = null;
  for (const [, date] of observedReports) {
    if (date) {
      const m = toMonthKey(date);
      if (!latestObservedMonth || compareMonths(m, latestObservedMonth) > 0) {
        latestObservedMonth = m;
      }
    }
  }

  // 1. Storage checks (prior to delivery date)
  const storageDates = getDatesByCode(observedReports, 'W30');
  const storageGaps = [];
  if (storageDates.length > 0 && deliveryDate) {
    const startStorageMonth = addMonths(toMonthKey(storageDates[0]), 1);
    const endStorageMonth = addMonths(toMonthKey(deliveryDate), -1);
    for (const m of monthRange(startStorageMonth, endStorageMonth)) {
      if (!observedMonthsSet.has(m)) {
        const prec = getPrecedingReport(observedReports, m);
        storageGaps.push({
          type: 'Storage',
          code: 'W30',
          month: m,
          isStrictGap: true,
          precedingSmr: prec?.smr ?? null,
          precedingDate: prec?.date ?? null,
        });
      }
    }
  }

  // 2. Service intervals
  const anchorDate = firstServiceDate || deliveryDate;
  const startServiceMonth = anchorDate ? addMonths(toMonthKey(anchorDate), 1) : null;

  const strictGaps = [...storageGaps];
  const nonCreatedReports = [];

  if (startServiceMonth && compareMonths(startServiceMonth, currentMonth) <= 0) {
    const allMonthsToCheck = monthRange(startServiceMonth, currentMonth);

    for (const m of allMonthsToCheck) {
      if (observedMonthsSet.has(m)) continue;

      // STRICT GAP: month is strictly between two existing reports
      const hasReportAhead = latestObservedMonth && compareMonths(latestObservedMonth, m) > 0;
      const prec = getPrecedingReport(observedReports, m);

      if (hasReportAhead) {
        strictGaps.push({
          type: 'Add. Service',
          code: 'W41X',
          month: m,
          isStrictGap: true,
          precedingSmr: prec?.smr ?? null,
          precedingDate: prec?.date ?? null,
        });
      } else {
        // NON-CREATED REPORT: Months after the latest existing report up to current month
        nonCreatedReports.push({
          type: 'Add. Service',
          code: 'W41X',
          month: m,
          isStrictGap: false,
          isPending: true,
          precedingSmr: prec?.smr ?? null,
          precedingDate: prec?.date ?? null,
        });
      }
    }
  }

  return {
    strictGaps,
    nonCreatedReports,
    monthlyGaps: [...strictGaps, ...nonCreatedReports],
  };
}

function shouldExpectThirdService(deliveryDate, currentMonth = getCurrentMonthKey()) {
  if (!deliveryDate) return false;
  return compareMonths(addMonths(toMonthKey(deliveryDate), 10), currentMonth) <= 0;
}

function buildStrictNextAction(missingReports, strictGaps, nonCreatedReports) {
  if (missingReports.length > 0) {
    return `Create the missing factory milestone(s): ${missingReports.join(', ')}.`;
  }
  if (strictGaps.length > 0) {
    const nextGap = strictGaps[0];
    return `Bridge strict gap for ${formatLifecycleMonth(nextGap.month)} (preceding SMR: ${nextGap.precedingSmr ?? 'N/A'} hrs).`;
  }
  if (nonCreatedReports.length > 0) {
    const nextPending = nonCreatedReports[0];
    return `Create pending monthly report for ${formatLifecycleMonth(nextPending.month)} to keep tracking current.`;
  }
  return 'All lifecycle milestones and monthly reports are completely up to date through current month.';
}


function getDatesByCode(observedReports, code) {
  return observedReports
    .filter(([reportCode]) => reportCode === code)
    .map(([, date]) => date)
    .sort();
}

function toMonthKey(dateValue) {
  return dateValue.slice(0, 7);
}

function addMonths(monthKey, amount) {
  const [year, month] = monthKey.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1 + amount, 1));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
}

function monthRange(startMonth, endMonth) {
  if (compareMonths(startMonth, endMonth) > 0) return [];

  const months = [];
  let cursor = startMonth;

  while (compareMonths(cursor, endMonth) <= 0) {
    months.push(cursor);
    cursor = addMonths(cursor, 1);
  }

  return months;
}

function compareMonths(left, right) {
  return left.localeCompare(right);
}

export function formatLifecycleDate(value) {
  if (!value) return '-';
  return new Date(`${value}T00:00:00`).toLocaleDateString('en-GB');
}

export function formatLifecycleMonth(value) {
  if (!value) return '-';
  return new Date(`${value}-01T00:00:00`).toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
}

export function getMachineReportMonths(machineNumber, generatedReports = [], liveEqpData = null) {
  const months = new Set();
  const mNum = String(machineNumber || '').trim();
  if (!mNum) return months;

  const liveMachinesMap = (liveEqpData && typeof liveEqpData === 'object') ? (liveEqpData.machines || liveEqpData) : {};
  const liveMachine = liveMachinesMap[mNum];

  let baseObserved = [];
  if (liveMachine && Array.isArray(liveMachine.reports) && liveMachine.reports.length > 0) {
    baseObserved = liveMachine.reports.map((r) => [r.eventCode, r.date]);
  } else if (OBSERVED_REPORTS[mNum]) {
    baseObserved = OBSERVED_REPORTS[mNum];
  }

  for (const [, date] of baseObserved) {
    if (date) months.add(String(date).slice(0, 7));
  }

  for (const r of generatedReports) {
    const reportMachine = String(r.machine_number || r.machine?.machineNumber || r.machine?.machine_number || '').trim();
    if (reportMachine === mNum) {
      const rawDate = r.service_date || r.created_at;
      if (rawDate) months.add(String(rawDate).slice(0, 7));
    }
  }

  return months;
}
